import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.item.*;
public final class EncounterBalanceCheck {
 static int checks;static void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 public static void main(String[]args)throws Exception{
  PrototypeIntegrationCheck.loaded();StringBuilder out=new StringBuilder("# Encounter role balance\n\nActual profile/stat/defence formulas; unmodified nonelite actors. Player level=2*tier, normal Warden sword when eligible (otherwise starter), starter hybrid mail at matching item level. No passives/skills, regeneration, block, damage map modifiers or travel. Incoming physical DPS includes map attack accuracy against equipped evasion and nonlinear armour per hit; elemental/chaos uses equipped resistances. Boss basic DPS excludes slam (24/32/44 raw at T1/3/6), windup/recovery pauses reduce sustained basic attacks. HP/player-DPS is a reference rather than discrete kill simulation.\n\n|Tier|Role|HP|Damage|Tick interval|Raw DPS|After player defences|Reference kill sec|\n|---:|---|---:|---:|---:|---:|---:|---:|\n");
  for(int tier:new int[]{1,3,6}){int level=tier*2;EquipmentBases.Base weapon=EquipmentBases.starter(true);for(EquipmentBases.Base b:EquipmentBases.all())if(level>=4&&b.itemId==22430)weapon=b;Item sword=EquipmentBases.create(weapon,level),mail=EquipmentBases.create(EquipmentBases.starter(false),level);Map<Stat,Double> stats=ArpgStats.equipment(new Item[]{sword,mail},level);double playerDps=(stats.get(Stat.PHYSICAL_MIN)+stats.get(Stat.PHYSICAL_MAX))/2*stats.get(Stat.ATTACK_SPEED)*(1+stats.get(Stat.CRITICAL_CHANCE)/100*(stats.get(Stat.CRITICAL_MULTIPLIER)/100-1))*Defences.hitChance(stats.get(Stat.ACCURACY),4*tier);double roleDps=0;
   for(int role=0;role<7;role++){EncounterProfiles.Profile p=EncounterProfiles.get(role);double raw=p.damage(tier)/(.6*p.attackTicks),taken=Defences.mitigate(p.damage(tier),p.damageType,stats,false)/(.6*p.attackTicks);if(p.damageType==DamageType.PHYSICAL)taken*=Defences.hitChance(100+(20+tier*5)*10,stats.get(Stat.EVASION));if(role<6)roleDps+=raw;check(p.health(tier,role==6)>0&&taken>=0&&taken<=raw,"Valid role health and damage");out.append(String.format(Locale.ROOT,"|%d|%s|%d|%d|%d|%.3f|%.3f|%.2f|%n",tier,p.id,p.health(tier,role==6),p.damage(tier),p.attackTicks,raw,taken,p.health(tier,role==6)/playerDps));}
   double baseline=(1+tier)/3.0;check(roleDps/6<=baseline*1.05,"Equal-role pack damage does not inflate baseline more than5percent");check(EncounterProfiles.get(6).damage(tier)==6+2*tier&&EncounterProfiles.get(6).health(tier,true)==120+35*tier,"Boss baseline preserved");}
  for(int role=0;role<6;role++)try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){
   Location area=f.area(6,4,role);MapRuns.MapMob mob=f.mob(area,false);f.stand(CombatPresentationCheck.offset(area,2,0));EncounterProfiles.Profile profile=EncounterProfiles.get(role,mob.getId());int first=mob.nextAttackTick;f.run.nextSlam=Integer.MAX_VALUE;for(int tick=1;tick<first;tick++){MapRuns.tick(f.p);check(mob.nextAttackTick==first,"Actor cannot strike before its initial per-NPC due time");}MapRuns.tick(f.p);check(mob.nextAttackTick==first+profile.attackTicks,"Actual strike advances the actor's own cadence");int due=mob.nextAttackTick;for(int tick=first+1;tick<due;tick++){MapRuns.tick(f.p);check(mob.nextAttackTick==due,"No early repeat attacks");}MapRuns.tick(f.p);check(mob.nextAttackTick==due+profile.attackTicks,"Actor repeats on its profile interval rather than global modulo5");check(mob.getHitpoints()==(int)(profile.health(1,false)*1.6),"Actual elite actor applies profile HP before elite scaling");}
  try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){Location area=f.area(6,4,2);MapRuns.MapMob caster=f.mob(area,false);f.stand(CombatPresentationCheck.offset(area,3,0));com.koios.game.map.MapRegion.getRegion(area.getX()+1,area.getY()).setClip(area.getX()+1,area.getY(),0,0xffffff);int due=caster.nextAttackTick;f.run.ticks=due-1;MapRuns.tick(f.p);check(caster.nextAttackTick==due,"Blocked shot does not consume attack cadence");}
  Files.write(Paths.get("../../logs/encounter-balance.md"),out.toString().getBytes(StandardCharsets.UTF_8));System.out.println("Passed "+checks+" encounter profile/balance/cadence checks.");
 }
}
